import os
from typing import Any, Dict, Optional

from google.cloud import monitoring_v3


def compare_metric_values(
    project_id: Optional[str],
    metric_type: str,
    resource_filter_a: str,
    resource_filter_b: str,
    start_time: Any,
    end_time: Any,
    aggregation: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Compare metric values for two resource or dimension filters over the same time window
    using Google Cloud Monitoring.

    Args:
        project_id: GCP project ID. If None, uses GOOGLE_CLOUD_PROJECT.
        metric_type: Cloud Monitoring metric type, e.g. "compute.googleapis.com/instance/cpu/utilization".
        resource_filter_a: Additional filter clause for the first resource/dimension set.
        resource_filter_b: Additional filter clause for the second resource/dimension set.
        start_time: RFC3339 string or protobuf Timestamp-compatible value.
        end_time: RFC3339 string or protobuf Timestamp-compatible value.
        aggregation: Optional aggregation config with keys like:
            alignment_period_seconds, per_series_aligner, cross_series_reducer,
            group_by_fields.

    Returns:
        Dict containing both query results and a simple comparison summary.
    """
    project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT") or os.environ.get("GCLOUD_PROJECT")
    if not project_id:
        raise ValueError("project_id is required or set GOOGLE_CLOUD_PROJECT/GCLOUD_PROJECT")

    client = monitoring_v3.MetricServiceClient()
    project_name = f"projects/{project_id}"

    def _build_filter(extra_clause: str) -> str:
        parts = [f'metric.type = "{metric_type}"']
        if extra_clause:
            parts.append(f"({extra_clause})")
        return " AND ".join(parts)

    def _make_interval():
        interval = monitoring_v3.TimeInterval()
        interval.start_time = start_time
        interval.end_time = end_time
        return interval

    def _apply_aggregation(request: monitoring_v3.ListTimeSeriesRequest) -> None:
        if not aggregation:
            return

        agg = monitoring_v3.Aggregation()
        if aggregation.get("alignment_period_seconds"):
            from google.protobuf.duration_pb2 import Duration

            agg.alignment_period = Duration(seconds=int(aggregation["alignment_period_seconds"]))
        if aggregation.get("per_series_aligner") is not None:
            agg.per_series_aligner = aggregation["per_series_aligner"]
        if aggregation.get("cross_series_reducer") is not None:
            agg.cross_series_reducer = aggregation["cross_series_reducer"]
        if aggregation.get("group_by_fields"):
            agg.group_by_fields.extend(list(aggregation["group_by_fields"]))

        request.aggregation = agg

    def _fetch(filter_clause: str) -> Dict[str, Any]:
        request = monitoring_v3.ListTimeSeriesRequest(
            name=project_name,
            filter=_build_filter(filter_clause),
            interval=_make_interval(),
            view=monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
        )
        _apply_aggregation(request)

        time_series = list(client.list_time_series(request=request))
        points = []
        total_value = 0.0

        for series in time_series:
            series_points = []
            for p in series.points:
                value = None
                which = p.value.WhichOneof("value")
                if which == "double_value":
                    value = float(p.value.double_value)
                elif which == "int64_value":
                    value = float(p.value.int64_value)
                elif which == "distribution_value":
                    dist = p.value.distribution_value
                    value = float(dist.mean) if dist.count else 0.0
                elif which == "string_value":
                    try:
                        value = float(p.value.string_value)
                    except Exception:
                        value = None

                if value is not None:
                    total_value += value

                series_points.append(
                    {
                        "interval_end": str(p.interval.end_time),
                        "value": value,
                    }
                )

            points.append(
                {
                    "metric": dict(series.metric),
                    "resource": dict(series.resource),
                    "points": series_points,
                }
            )

        return {
            "filter": filter_clause,
            "time_series_count": len(time_series),
            "total_value": total_value,
            "time_series": points,
        }

    result_a = _fetch(resource_filter_a)
    result_b = _fetch(resource_filter_b)

    a = result_a["total_value"]
    b = result_b["total_value"]
    delta = a - b
    pct = None if b == 0 else (delta / b) * 100.0

    return {
        "window": {
            "start_time": str(start_time),
            "end_time": str(end_time),
        },
        "metric_type": metric_type,
        "a": result_a,
        "b": result_b,
        "comparison": {
            "difference": delta,
            "percent_difference_vs_b": pct,
            "higher": "a" if a > b else "b" if b > a else "equal",
        },
    }
